#include <ctype.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "x11shim/xshim.h"

static const char *const *g_defaults;

static const char *const *g_overrides;

void xshim_set_defaults(const char *const *defaults) { g_defaults = defaults; }
void xshim_set_overrides(const char *const *overrides) {
  g_overrides = overrides;
}

/* What xscreensaver's app-defaults file supplies to the xlockmore framework.
 * A hack's own defaults take precedence. */
static const struct {
  const char *name;
  const char *value;
} kFrameworkDefaults[] = {
    {"delta3d", "1.5"}, {"right3d", "red"},  {"left3d", "blue"},
    {"both3d", "magenta"}, {"none3d", "black"}, {"size", "0"},
};

/* Finds "<.|*>name:<ws>value" in a NULL-terminated list, or returns NULL. */
static const char *find_in(const char *const *list, const char *name) {
  size_t len = strlen(name);
  for (const char *const *p = list; p && *p; p++) {
    const char *s = *p;
    if (*s == '.' || *s == '*') s++;
    if (strncmp(s, name, len) != 0 || s[len] != ':') continue;
    s += len + 1;
    while (*s && isspace((unsigned char)*s)) s++;
    return s;
  }
  return NULL;
}

static const char *lookup(const char *name) {
  const char *v = find_in(g_overrides, name);
  if (!v) v = find_in(g_defaults, name);
  if (v) return v;
  for (size_t i = 0; i < sizeof(kFrameworkDefaults) / sizeof(*kFrameworkDefaults);
       i++)
    if (strcmp(kFrameworkDefaults[i].name, name) == 0)
      return kFrameworkDefaults[i].value;
  return NULL;
}

static const struct {
  const char *name;
  uint8_t r, g, b;
} kColours[] = {
    {"black", 0, 0, 0},     {"white", 255, 255, 255}, {"red", 255, 0, 0},
    {"green", 0, 255, 0},   {"blue", 0, 0, 255},      {"yellow", 255, 255, 0},
    {"magenta", 255, 0, 255}, {"cyan", 0, 255, 255},  {"orange", 255, 165, 0},
};

static int colour_from_spec(const char *v, uint8_t *r, uint8_t *g,
                            uint8_t *b) {
  size_t tok = 0;
  while (v[tok] && !isspace((unsigned char)v[tok])) tok++;
  for (size_t i = 0; i < sizeof(kColours) / sizeof(kColours[0]); i++)
    if (strlen(kColours[i].name) == tok &&
        strncasecmp(v, kColours[i].name, tok) == 0) {
      *r = kColours[i].r;
      *g = kColours[i].g;
      *b = kColours[i].b;
      return 1;
    }
  unsigned ur, ug, ub;
  if (*v == '#' && strlen(v) >= 7 &&
      sscanf(v + 1, "%2x%2x%2x", &ur, &ug, &ub) == 3) {
    *r = (uint8_t)ur;
    *g = (uint8_t)ug;
    *b = (uint8_t)ub;
    return 1;
  }
  return 0;
}

Status XParseColor(Display *dpy, Colormap cmap, const char *spec, XColor *c) {
  (void)dpy;
  (void)cmap;
  uint8_t r, g, b;
  if (!spec || !colour_from_spec(spec, &r, &g, &b)) return 0;
  c->red = (unsigned short)(r * 0x101);
  c->green = (unsigned short)(g * 0x101);
  c->blue = (unsigned short)(b * 0x101);
  c->flags = DoRed | DoGreen | DoBlue;
  return 1;
}

static void warn_missing(const char *name) {
  fprintf(stderr, "xshim: no default for resource '%s'\n", name);
}

int get_integer_resource(Display *dpy, const char *name, const char *cls) {
  (void)dpy;
  (void)cls;
  const char *v = lookup(name);
  if (!v) {
    warn_missing(name);
    return 0;
  }
  return (int)strtol(v, NULL, 0);
}

double get_float_resource(Display *dpy, const char *name, const char *cls) {
  (void)dpy;
  (void)cls;
  const char *v = lookup(name);
  if (!v) {
    warn_missing(name);
    return 0;
  }
  return strtod(v, NULL);
}

Bool get_boolean_resource(Display *dpy, const char *name, const char *cls) {
  (void)dpy;
  (void)cls;
  const char *v = lookup(name);
  if (!v) return False;
  return strncasecmp(v, "true", 4) == 0 || strncasecmp(v, "on", 2) == 0 ||
         strncasecmp(v, "yes", 3) == 0 || *v == '1';
}

char *get_string_resource(Display *dpy, const char *name, const char *cls) {
  (void)dpy;
  (void)cls;
  const char *v = lookup(name);
  return v ? strdup(v) : NULL;
}

unsigned long xshim_background_pixel(void) {
  return lookup("background")
             ? get_pixel_resource(NULL, 1, "background", "Background")
             : 0;
}

unsigned long get_pixel_resource(Display *dpy, Colormap cmap, const char *name,
                                 const char *cls) {
  (void)dpy;
  (void)cmap;
  (void)cls;
  const char *v = lookup(name);
  if (!v) {
    warn_missing(name);
    return 0;
  }
  uint8_t r, g, b;
  if (colour_from_spec(v, &r, &g, &b)) return rgb565(r, g, b);
  fprintf(stderr, "xshim: unknown colour '%s' for '%s'\n", v, name);
  return 0xFFFF;
}
#include "runner/hack_runner.h"

#include <stdlib.h>

#include "hacks/registry.h"
#include "screenhackI.h"
#include "x11shim/xshim.h"

#define RUNNER_WINDOW ((Window)1)

struct HackRunner {
  Canvas *canvas;
  Display *dpy;
  const HackEntry *const *hacks;
  int count;
  int index;
  void *closure;
  int running;
};

HackRunner *runner_create_with(Canvas *canvas, const HackEntry *const *hacks,
                               int count) {
  HackRunner *r = (HackRunner *)calloc(1, sizeof(*r));
  if (!r) return NULL;
  r->canvas = canvas;
  r->dpy = xshim_open_display(canvas);
  r->hacks = hacks;
  r->count = count;
  if (!r->dpy) {
    free(r);
    return NULL;
  }
  return r;
}

HackRunner *runner_create(Canvas *canvas) {
  return runner_create_with(canvas, g_hacks, g_hack_count);
}

typedef struct {
  const char *const *defaults;
  void *(*init)(Display *, Window);
  unsigned long (*draw)(Display *, Window, void *);
  void (*free)(Display *, Window, void *);
  void *setup_arg; /* xlockmore_init's hidden third argument; NULL otherwise */
  int has_setup_arg;
} Callbacks;

/* An xlockmore hack's table is empty until its setup_cb has run, and that
 * allocates, so run it once rather than on every button press. */
static Callbacks callbacks_for(const HackEntry *e) {
  struct xscreensaver_function_table *t = e->xsft;
  if (!t) return (Callbacks){e->defaults, e->init, e->draw, e->free, NULL, 0};
  if (!t->init_cb && t->setup_cb) t->setup_cb(t, t->setup_arg);
  return (Callbacks){t->defaults, t->init_cb, t->draw_cb, t->free_cb,
                     t->setup_arg, 1};
}

static void stop(HackRunner *r) {
  if (!r->running) return;
  callbacks_for(r->hacks[r->index]).free(r->dpy, RUNNER_WINDOW, r->closure);
  r->closure = NULL;
  r->running = 0;
}

void runner_destroy(HackRunner *r) {
  if (!r) return;
  stop(r);
  xshim_close_display(r->dpy);
  free(r);
}

int runner_start(HackRunner *r, int index) {
  if (index < 0 || index >= r->count) return -1;
  stop(r);
  r->index = index;
  const Callbacks cb = callbacks_for(r->hacks[index]);
  xshim_set_defaults(cb.defaults);
  xshim_set_overrides(r->hacks[index]->overrides);
  canvas_clear(r->canvas, (uint16_t)xshim_background_pixel());
  if (cb.has_setup_arg) {
    /* Like screenhack.c: init_cb is declared with two arguments, but the
     * xlockmore one takes its function table as a third. */
    void *(*init3)(Display *, Window, void *) =
        (void *(*)(Display *, Window, void *))cb.init;
    r->closure = init3(r->dpy, RUNNER_WINDOW, cb.setup_arg);
  } else {
    r->closure = cb.init(r->dpy, RUNNER_WINDOW);
  }
  r->running = 1;
  return 0;
}

unsigned long runner_step(HackRunner *r) {
  if (!r->running) return RUNNER_MAX_DELAY_US;
  unsigned long d =
      callbacks_for(r->hacks[r->index]).draw(r->dpy, RUNNER_WINDOW, r->closure);
  if (d < RUNNER_MIN_DELAY_US) return RUNNER_MIN_DELAY_US;
  if (d > RUNNER_MAX_DELAY_US) return RUNNER_MAX_DELAY_US;
  return d;
}

unsigned long runner_remaining_delay_us(unsigned long requested_us,
                                        unsigned long spent_us) {
  return requested_us > spent_us ? requested_us - spent_us : 0;
}

int runner_next(HackRunner *r) {
  runner_start(r, (r->index + 1) % r->count);
  return r->index;
}

int runner_prev(HackRunner *r) {
  runner_start(r, (r->index + r->count - 1) % r->count);
  return r->index;
}

int runner_index(const HackRunner *r) { return r->index; }
